"use server"
import { revalidatePath } from "next/cache"
import { connectdb } from "../lib/db"
import {User,Post} from "../lib/models"

export default async function Getuserandpost(username:string){
    try{
await connectdb()
const [user,post]=await Promise.all([
    User.findOne({userId:username}).lean(),
    Post.find().populate("author","name").sort({createdAt: -1}).lean()
])
if(!user){
    return {success: false, error: "user not found for getting post"}
}
return{
    success:true,
    userData:JSON.parse(JSON.stringify(user)),
    postData:JSON.parse(JSON.stringify(post))
}
    }catch(error){
        console.error(error)
           return{success:false,error:"error while parallel querying"}
    }
 
}
export async function Crpost(data:{
    title:string,content:string,name:string
}){
    try{
await connectdb()
const finduser=await User.findOne({userId:data.name})
if(!finduser){
    return {success:false,error:"user not found"}
}
const createpost=await Post.create({
    title:data.title,
    content:data.content,
    author:finduser._id,
})
revalidatePath("/")
return{
    success: true,
    post: JSON.parse(JSON.stringify(createpost))
}
    }catch(error){
        console.error(error)
        return {success:false,error:"error while creating post"}
    }
}